// Simple endless runner game targeting <canvas id="game"></canvas>
// Ship moves upward on click/tap, gravity pulls down, asteroids appear randomly.
(function(){
  const canvas = document.getElementById('game');
  if(!canvas){ console.error('Canvas #game not found'); return; }
  const ctx = canvas.getContext('2d');
  const W = canvas.width = canvas.clientWidth || 800;
  const H = canvas.height = canvas.clientHeight || 600;

  // Game objects
  const ship = { x: 80, y: H/2, w: 30, h: 20, vy: 0 };
  const asteroids = [];
  const STAR_COUNT = 100;
  const stars = [];
  for(let i=0;i<STAR_COUNT;i++){
    stars.push({x: Math.random()*W, y: Math.random()*H, r: Math.random()*2});
  }

  let lastTime = 0;
  let gameOver = false;

input.oldString:
function draw(){
    // clear
    ctx.fillStyle = '#000';
    ctx.fillRect(0,0,W,H);
    // stars
    ctx.fillStyle = '#fff';
    for(const s of stars){
      ctx.beginPath();
      ctx.arc(s.x, s.y, s.r,0,Math.PI*2);
      ctx.fill();
    }
    // ship (triangle)
    ctx.fillStyle = '#0f0';
    ctx.beginPath();
    ctx.moveTo(ship.x, ship.y);
    ctx.lineTo(ship.x, ship.y + ship.h);
    ctx.lineTo(ship.x + ship.w, ship.y + ship.h/2);
    ctx.closePath();
    ctx.fill();
    // asteroids (circles)
    ctx.fillStyle = '#888';
    for(const a of asteroids){
      ctx.beginPath();
      ctx.arc(a.x + a.w/2, a.y + a.h/2, a.w/2,0,Math.PI*2);
      ctx.fill();
    }
    // game over overlay
    if(gameOver){
      ctx.fillStyle = 'rgba(0,0,0,0.6)';
      ctx.fillRect(0,0,W,H);
      ctx.fillStyle = '#fff';
      ctx.font = '48px sans-serif';
      ctx.textAlign = 'center';
      ctx.fillText('Game Over', W/2, H/2);
    }
  }

